// Generates src/services/authoring/bundled-libs.generated.ts — the TypeScript
// standard-library .d.ts text the authoring worker's typecheck needs in its VFS
// (there is no filesystem in a Worker). Computed as the transitive
// `/// <reference lib="…" />` closure of the default lib for the worker's target
// (ES2020 full → es2020 + dom + …), read from the installed `typescript` package.
//
// This file is GENERATED at build time (a prebuild of `build:authoring-worker`) and
// gitignored — never checked in (ways_of_working §9: generators emit their output,
// lists of generated content don't get committed). Keeping it out of git also keeps
// ~2.5 MB of lib text out of the repo.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const libDir = join(here, '..', 'node_modules', 'typescript', 'lib');
const outFile = join(here, '..', 'src', 'services', 'authoring', 'bundled-libs.generated.ts');

// The worker's `COMPILER_OPTIONS.target` is ES2020 (typecheck.ts) → default lib.
const DEFAULT_LIB = 'lib.es2020.full.d.ts';

/** Map a `/// <reference lib="dom" />` token to its file name. */
const libFile = (name) => `lib.${name.toLowerCase()}.d.ts`;
const REF_RE = /\/\/\/\s*<reference\s+lib\s*=\s*"([^"]+)"\s*\/>/g;

// BFS the reference graph so every lib a `full` file pulls in is embedded.
const collected = new Map(); // basename → text
const queue = [DEFAULT_LIB];
while (queue.length) {
  const file = queue.shift();
  if (collected.has(file)) continue;
  const path = join(libDir, file);
  if (!existsSync(path)) {
    throw new Error(`gen-authoring-libs: referenced lib not found: ${file}`);
  }
  const text = readFileSync(path, 'utf8');
  collected.set(file, text);
  for (const m of text.matchAll(REF_RE)) queue.push(libFile(m[1]));
}

const entries = [...collected.entries()].sort(([a], [b]) => (a < b ? -1 : 1));
const banner =
  '// GENERATED by scripts/gen-authoring-libs.mjs — DO NOT EDIT, DO NOT COMMIT.\n' +
  `// TypeScript ${JSON.parse(readFileSync(join(libDir, '..', 'package.json'), 'utf8')).version}` +
  ` standard-lib .d.ts closure of ${DEFAULT_LIB} (${entries.length} files).\n` +
  '/* eslint-disable */\n';

const body =
  `export const DEFAULT_LIB = ${JSON.stringify(DEFAULT_LIB)} as const;\n\n` +
  'export const BUNDLED_LIBS: Record<string, string> = {\n' +
  entries.map(([name, text]) => `  ${JSON.stringify(name)}: ${JSON.stringify(text)},`).join('\n') +
  '\n};\n';

writeFileSync(outFile, banner + body);
const bytes = entries.reduce((n, [, t]) => n + t.length, 0);
console.log(
  `gen-authoring-libs: wrote ${entries.length} libs (${(bytes / 1024 / 1024).toFixed(2)} MB) → ${outFile}`,
);
